/// <summary>
/// The extension class for Product Receipt journal creation.
/// </summary>
[ExtensionOf(classStr(PurchPackingSlipJournalCreate))]
final class METPurchPackingSlipJournalCreate_Extension
{
}

Method.Source:
    /// <summary>
    /// Extension of create journal line method for product receipt.
    /// </summary>
    /// <param name = "_purchParmLine">The purch parm line buffer.</param>
    protected void createJournalLine(Common _purchParmLine)
    {
        #OCCRetryCount
        InventSite inventSite;
        METInventItemOrderSetup metInventItemOrderSetup;
        InventDim inventDim;
        PurchParmLine purchParmLine = _purchParmLine as PurchParmLine;

        next createJournalLine(_purchParmLine);

        try
        {
            select firstonly METAutoUpdateItemStatusUponReceipt, SiteId
                from inventSite
                join firstonly forupdate metInventItemOrderSetup
                where metInventItemOrderSetup.ItemId == purchParmLine.ItemId
                && metInventItemOrderSetup.SiteId == inventSite.SiteId
                exists join inventDim
                where inventDim.inventDimId == purchParmLine.InventDimId
                && inventDim.InventSiteId == inventSite.SiteId;

            if (inventSite && inventSite.METAutoUpdateItemStatusUponReceipt && !metInventItemOrderSetup)
            {
                METInventItemOrderSetup metInventItemOrderSetupLocal;

                metInventItemOrderSetupLocal.ItemId = purchParmLine.ItemId;
                metInventItemOrderSetupLocal.InventDimId = purchParmLine.InventDimId;
                metInventItemOrderSetupLocal.SiteId = inventSite.SiteId;
                metInventItemOrderSetupLocal.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
                metInventItemOrderSetupLocal.insert();                
                info(strFmt("@MET:StatusDoesNotExist", inventSite.SiteId));
            }
            else if (inventSite && inventSite.METAutoUpdateItemStatusUponReceipt && metInventItemOrderSetup
                && (metInventItemOrderSetup.ItemStatus == METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus || metInventItemOrderSetup.ItemStatus == ''))
            { 
                metInventItemOrderSetup.ItemStatus          = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
                metInventItemOrderSetup.PublishPriceBook    = true;
                metInventItemOrderSetup.PublishPortal       = true;
                metInventItemOrderSetup.PublishHost         = true;
                metInventItemOrderSetup.update();
                //info(strFmt("@MET:ItemSiteUpdated",metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId, metInventItemOrderSetup.ItemStatus));            

                // Update child items as well.
                METInventItemOrderSetup::updateChildItemSiteStatus(purchParmLine.ItemId, inventSite.SiteId);
                this.itemStatusToTransferDependSites(metInventItemOrderSetup, InventDim::find(purchParmLine.InventDimId).InventLocationId);
            }

            // CB232_AutoSettingItemStockStatus.
            // Resets item stock status from LTNA to blank.
            METInventItemOrderSetup::resetItemStockLTNAStatus(purchParmLine.ItemId, inventSite.SiteId);
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }

    /// <summary>
    /// Change Item status to transfer dependent sites
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
    public void itemStatusToTransferDependSites(METInventItemOrderSetup _metInventItemOrderSetup, InventLocationId _inventLocationIdFromPO)
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;
        METInventItemOrderSetup metInventItemOrderSetupSupplySite;
        InventParameters inventParameters = InventParameters::find();
        METItemStatusWarehouses metItemStatusWarehouses;
        

        //Activate all transfer sites
        METChangeItemStatusHelper metChangeItemStatusHelper = new METChangeItemStatusHelper();
        metChangeItemStatusHelper.updateItemStatusOfTransferSite(_metInventItemOrderSetup.ItemId, _metInventItemOrderSetup.SiteId, METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus);
        
        // Intercompany case - Check for warehouse value in other legal entity
        if (_inventLocationIdFromPO)
        {
            InventLocation inventLocationNDC;                

            InventLocationId warehouse = _inventLocationIdFromPO;
            container warehouseCon;

            if(InventLocation::find(warehouse).METNDCWarehouse)
            {
                while select InventLocationId from inventLocationNDC
                    where inventLocationNDC.METNDCWarehouse == NoYes::Yes
                {
                    warehouseCon += inventLocationNDC.InventLocationId;
                }
            }
            else
            {
                warehouseCon += warehouse;
            }
                
            changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
            { 
                METReqItemTableInventDimView metReqItemTableInventDimViewIntCom;
                METItemStatusWarehouses metItemStatusWarehousesIntCom;

                while select ItemId,CovInventDimId,ReqPOType,InventLocationIdReqMain, VendId, VendIntercompanyWarehouse
                    from metReqItemTableInventDimViewIntCom
                    where metReqItemTableInventDimViewIntCom.ItemId == _metInventItemOrderSetup.ItemId
                        && metReqItemTableInventDimViewIntCom.ReqPOType == ReqPOType::Purch
                        && metReqItemTableInventDimViewIntCom.METInterCompanySourced == NoYes::Yes
                    notexists join metItemStatusWarehousesIntCom
                    where metItemStatusWarehousesIntCom.InventLocationId == metReqItemTableInventDimViewIntCom.InventLocationId
                {                        
                    if (conFind(warehouseCon, metReqItemTableInventDimViewIntCom.VendIntercompanyWarehouse))
                    {
                        METInventItemOrderSetup metInventItemOrderSetupIntComp = METInventItemOrderSetup::findByItemAndSite(metReqItemTableInventDimViewIntCom.ItemId, InventDim::find(metReqItemTableInventDimViewIntCom.CovInventDimId).InventSiteId);
                        this.updateStatusToActive(metInventItemOrderSetupIntComp);
                        METInventItemOrderSetup::updateChildItemSiteStatus(metInventItemOrderSetupIntComp.ItemId, metInventItemOrderSetupIntComp.SiteId);

                        //Activate all transfer sites
                        METChangeItemStatusHelper metChangeItemStatusHelperIntCom = new METChangeItemStatusHelper();
                        metChangeItemStatusHelperIntCom.updateItemStatusOfTransferSite(metReqItemTableInventDimViewIntCom.ItemId, metInventItemOrderSetupIntComp.SiteId, METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus);
                    }                        
                }
            }
        }
        
    }

/// <summary>
/// Update Item status to Active
/// </summary>
/// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup table</param>
public void updateStatusToActive(METInventItemOrderSetup _metInventItemOrderSetup)
{
    if(_metInventItemOrderSetup)
    {
        _metInventItemOrderSetup.selectForUpdate(true);
        _metInventItemOrderSetup.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
        _metInventItemOrderSetup.PublishPriceBook = NoYes::Yes;
        _metInventItemOrderSetup.PublishPortal = NoYes::Yes;
        _metInventItemOrderSetup.PublishHost = NoYes::Yes;
        _metInventItemOrderSetup.update();
        info(strFmt("@MET:ItemSiteUpdated",_metInventItemOrderSetup.ItemId, _metInventItemOrderSetup.SiteId, _metInventItemOrderSetup.ItemStatus));
    }
}

    /// <summary>
    /// This method bypass the catch weight logic.
    /// </summary>
    /// <param name = "_localPurchParmLine">PurchParmLine buffer</param>
    /// <param name = "_inventMovement">InventMov_Purch class instance</param>
    /// <param name = "_vendPackingSlipTrans">VendPackingSlipTrans buffer</param>
    /// <returns>Invent quantity</returns>
    protected InventQty getCatchWeight(
        PurchParmLine               _localPurchParmLine,
        InventMov_Purch             _inventMovement,
        VendPackingSlipTrans        _vendPackingSlipTrans)
    {
        InventQty   ret;
        Common      inventBuffer = _inventMovement.buffer();
        PurchLine   localPurchLine;
        InventTrans localInventTrans;
        PurchLine   purchLine;
        InventTransOrigin inventTransOrigin;
 
        select forUpdate localInventTrans
            join inventTransOrigin
                where inventTransOrigin.RecId           == localInventTrans.InventTransOrigin
                    && localInventTrans.StatusReceipt   == StatusReceipt::Registered
            join purchLine
                where purchLine.RecId           == _localPurchParmLine.PurchLineRecId
                    && purchLine.InventTransId  == inventTransOrigin.InventTransId;


        PdsCWInventQty  localPdsCWQty       = localInventTrans.PdsCWQty;
       
        // checking buffer is PurchLine or not
        if (inventBuffer is PurchLine)
        {
            localPurchLine = inventBuffer as PurchLine;
        
            // Adjust the CW update to match the CW quantity if it is lower, to preserve the registered quantity.
            if (_localPurchParmLine.pdsCwReceiveNow < localPdsCWQty)
            {
                _localPurchParmLine.pdsCwReceiveNow = localPdsCWQty;
            }

            ttsbegin;
            localInventTrans.PdsCWQty = _localPurchParmLine.pdsCwReceiveNow;
            localInventTrans.doUpdate();
            ttscommit;
        }

        ret = next getCatchWeight(_localPurchParmLine, _inventMovement, _vendPackingSlipTrans);

        if (inventBuffer is PurchLine)
        {
            ttsbegin;
            localInventTrans.PdsCWQty = localPdsCWQty;
            localInventTrans.doUpdate();
            ttscommit;
        }

        return ret;
    }
